declare(strict_types=1);require __DIR__.'/v10-lib.php';$u=require_login();if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST')json_response(['ok'=>false,'error'=>'method_not_allowed'],405);verify_csrf();if(empty($_FILES['file'])||!is_uploaded_file($_FILES['file']['tmp_name']))json_response(['ok'=>false,'error'=>'file_required'],422);$f=$_FILES['file'];if((int)$f['error']!==UPLOAD_ERR_OK)json_response(['ok'=>false,'error'=>'upload_error'],422);if((int)$f['size']>15*1024*1024)json_response(['ok'=>false,'error'=>'file_too_large'],413);$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($f['tmp_name'])?:'';$allowed=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'=>'xlsx','application/vnd.openxmlformats-officedocument.wordprocessingml.document'=>'docx','application/vnd.openxmlformats-officedocument.presentationml.presentation'=>'pptx','text/plain'=>'txt','text/csv'=>'csv'];if(!isset($allowed[$mime]))json_response(['ok'=>false,'error'=>'unsupported_file_type','mime'=>$mime],415);$cid=(int)$u['company_id'];$entity=(string)($_POST['entity_type']??'');$eid=(int)($_POST['entity_id']??0);$meta=v10_meta($entity);require_cap_v10($meta['write']);if($entity&&$eid)v10_require_record($entity,$eid,$cid);$stored=bin2hex(random_bytes(24)).'.'.$allowed[$mime];$dir=v10_storage_dir('private_uploads').'/'.$cid;if(!is_dir($dir)&&!mkdir($dir,0700,true)&&!is_dir($dir))json_response(['ok'=>false,'error'=>'storage_unavailable'],500);if(!is_writable($dir))json_response(['ok'=>false,'error'=>'storage_not_writable'],500);$dest=$dir.'/'.$stored;if(!move_uploaded_file($f['tmp_name'],$dest))json_response(['ok'=>false,'error'=>'store_failed'],500);@chmod($dest,0600);$title=trim((string)($_POST['title']??pathinfo((string)$f['name'],PATHINFO_FILENAME)))?:'Document';$project=$entity==='projects'?$eid:null;$customer=$entity==='customers'?$eid:null;$task=$entity==='tasks'?$eid:null;$relative='private://'.$cid.'/'.$stored;$st=db()->prepare('INSERT INTO documents(company_id,project_id,customer_id,task_id,title,category,file_url,version_label,uploaded_by) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute([$cid,$project,$customer,$task,$title,trim((string)($_POST['category']??'general')),$relative,trim((string)($_POST['version_label']??''))?:null,$u['id']]);$id=(int)db()->lastInsertId();if($entity&&$eid)db()->prepare('INSERT INTO v10_document_links(company_id,document_id,entity_type,entity_id) VALUES(?,?,?,?)')->execute([$cid,$id,$entity,$eid]);audit('upload','document',$id,['mime'=>$mime,'size'=>(int)$f['size']]);if($entity&&$eid)v10_timeline($entity,$eid,'file','File uploaded',$title,'document',$id,(int)$u['id']);json_response(['ok'=>true,'id'=>$id,'title'=>$title]);
